import { useSensorData, useSystem, useConnection, useAISuggestions, useSensorStore } from '@store/sensorStore';
import { Thermometer, Droplets, Flame, AlertTriangle, Zap, Droplet, Wifi, Database } from 'lucide-react';
import { AreaChart, Area, ResponsiveContainer } from 'recharts';
import { useState, useEffect } from 'react';

interface SensorConfig {
  key: string;
  label: string;
  unit: string;
  icon: typeof Thermometer;
  color: string;
  min: number;
  max: number;
}

const sensorConfig: SensorConfig[] = [
  { key: 'AirTemp', label: 'Air Temp', unit: '°C', icon: Thermometer, color: '#ef4444', min: -10, max: 50 },
  { key: 'SoilTemp', label: 'Soil Temp', unit: '°C', icon: Thermometer, color: '#f97316', min: -10, max: 50 },
  { key: 'AirHumidity', label: 'Humidity', unit: '%', icon: Droplets, color: '#06b6d4', min: 0, max: 100 },
  { key: 'SoilMoisture', label: 'Soil Moisture', unit: '%', icon: Droplet, color: '#22c55e', min: 0, max: 100 },
  { key: 'VOC', label: 'VOC Index (MQ135)', unit: 'index', icon: Flame, color: '#fbbf24', min: 0, max: 500 },
];

export function Dashboard() {
  const sensorData = useSensorData();
  const system = useSystem();
  const { connected } = useConnection();
  const suggestions = useAISuggestions();
  const { sendCommand } = useSensorStore();
  const [history, setHistory] = useState<Record<string, number[]>>({});

  useEffect(() => {
    if (!sensorData) return;
    setHistory((previous) => {
      const next = { ...previous };
      for (const { key } of sensorConfig) {
        const value = sensorData[key as keyof typeof sensorData];
        if (typeof value === 'number') next[key] = [...(next[key] ?? []).slice(-49), value];
      }
      return next;
    });
  }, [sensorData]);

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold">Greenhouse Dashboard</h1>
          <p className="text-[var(--text-muted)] mt-1">Live readings from {system?.deviceId ?? 'the deployed device'}</p>
        </div>
        <span className={`status-dot ${connected ? 'online' : 'offline'}`}>{connected ? 'LIVE' : 'OFFLINE'}</span>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {sensorConfig.map((config) => <SensorCard key={config.key} data={sensorData} config={config} history={history[config.key] ?? []} />)}
      </div>
      <section className="card">
        <h2 className="text-lg font-semibold">System controls</h2>
        <p className="text-sm text-[var(--text-muted)] mt-1">{Object.keys(suggestions).length} AI suggestions available. Climate observations are informational and never control actuators.</p>
        <div className="flex flex-wrap gap-2 mt-4">
          <button className="btn btn-primary" onClick={() => sendCommand({ target: 'pump', action: 'ON', mode: 'MANUAL' })}><Droplets className="w-4 h-4" />Irrigate</button>
          <button className="btn btn-secondary" onClick={() => sendCommand({ target: 'pump', action: 'OFF', mode: 'MANUAL' })}><AlertTriangle className="w-4 h-4" />Stop pump</button>
          <button className="btn btn-secondary" onClick={() => sendCommand({ target: 'buzzer', action: 'MUTE', mode: 'MANUAL' })}><Zap className="w-4 h-4" />Mute buzzer</button>
          <button className="btn btn-secondary" onClick={() => sendCommand({ target: 'system', action: 'CALIBRATE', mode: 'MANUAL' })}><Database className="w-4 h-4" />Calibrate</button>
          <button className="btn btn-secondary" onClick={() => sendCommand({ target: 'system', action: 'REBOOT', mode: 'MANUAL' })}><Wifi className="w-4 h-4" />Reboot</button>
        </div>
      </section>
    </div>
  );
}

function SensorCard({ data, config, history }: { data: any; config: SensorConfig; history: number[] }) {
  const value = data?.[config.key];
  const percentage = Math.max(0, Math.min(100, ((value - config.min) / (config.max - config.min)) * 100));
  const Icon = config.icon;
  return (
    <div className="card glass-hover group relative overflow-hidden">
      <div className="flex items-start justify-between mb-3 gap-2">
        <div className="min-w-0 flex-1">
          <p className="text-xs text-[var(--text-muted)] truncate mb-1"><Icon className="w-3.5 h-3.5 inline-block mr-1 -mt-0.5" style={{ color: config.color }} />{config.label}</p>
          <p className="text-lg font-bold font-mono text-[var(--text-primary)] whitespace-nowrap">{typeof value === 'number' ? value.toFixed(1) : '—'}<span className="text-[11px] font-normal text-[var(--text-muted)] ml-1">{config.unit}</span></p>
        </div>
        <div className="w-14 h-14 relative flex-shrink-0"><svg className="w-full h-full transform -rotate-90" viewBox="0 0 32 32" role="img" aria-hidden="true"><circle cx="16" cy="16" r="12" fill="none" stroke="var(--border-primary)" strokeWidth="3" /><circle cx="16" cy="16" r="12" fill="none" stroke={config.color} strokeWidth="3" strokeDasharray={`${percentage * 1.51} 151`} strokeLinecap="round" className="transition-all duration-1000" style={{ filter: `drop-shadow(0 0 4px ${config.color})` }} /></svg></div>
      </div>
      <div className="h-12">{history.length ? <ResponsiveContainer width="100%" height="100%"><AreaChart data={history.map((v, i) => ({ time: i, value: v }))}><Area type="monotone" dataKey="value" stroke={config.color} fill={config.color} fillOpacity={0.15} strokeWidth={2} /></AreaChart></ResponsiveContainer> : <p className="text-xs text-[var(--text-muted)]">No in-session trend yet.</p>}</div>
    </div>
  );
}
