import { useCallback, useEffect, useState } from 'react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { endpoints } from '@/services/api';
import type { ClimateHistoryResult, ExternalClimateObservation } from '@shared/types';

const DAY_MS = 86_400_000;
const RANGE_DAYS = 30;

function dateKey(date: Date): string {
  return date.toISOString().slice(0, 10).replace(/-/g, '');
}

function defaultRange(): { start: string; end: string } {
  const now = new Date();
  return { start: dateKey(new Date(now.getTime() - (RANGE_DAYS - 1) * DAY_MS)), end: dateKey(now) };
}

function asInputDate(value: string): string {
  return `${value.slice(0, 4)}-${value.slice(4, 6)}-${value.slice(6, 8)}`;
}

function fromInputDate(value: string): string {
  return value.replace(/-/g, '');
}

function climateFetchError(error: unknown): string {
  const status = (error as { response?: { status?: number } })?.response?.status;
  return status === 503 ? 'NASA POWER is temporarily unavailable. Try again later.' : 'Climate data could not be loaded.';
}

export function ClimateSection() {
  const initialRange = defaultRange();
  const [range, setRange] = useState(initialRange);
  const [observations, setObservations] = useState<ExternalClimateObservation[]>([]);
  const [stale, setStale] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadHistory = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await endpoints.getClimateHistory(range) as { data: ClimateHistoryResult };
      setObservations(response.data.observations);
      setStale(response.data.cache.stale);
    } catch (requestError) {
      setError(climateFetchError(requestError));
      setObservations([]);
    } finally {
      setLoading(false);
    }
  }, [range]);

  useEffect(() => { void loadHistory(); }, [loadHistory]);

  const latest = [...observations].reverse().find((item) => item.dataStatus === 'available' || item.dataStatus === 'partially_available' || item.dataStatus === 'stale');
  const rows = observations.filter((item) => item.airTemperatureC !== null || item.relativeHumidityPercent !== null);

  return (
    <section className="card space-y-4" aria-labelledby="external-climate-heading">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h2 id="external-climate-heading" className="text-lg font-semibold">External climate · Cairo</h2>
          <p className="mt-1 text-sm text-[var(--text-muted)]">
            NASA POWER daily gridded outdoor estimates. Separate from greenhouse sensors; not live weather.
          </p>
        </div>
        <div className="flex items-center gap-2 text-xs text-[var(--text-muted)]">
          <label htmlFor="climate-start">From</label>
          <input id="climate-start" aria-label="Climate history start date" className="input w-auto" type="date" value={asInputDate(range.start)} max={asInputDate(range.end)} onChange={(event) => setRange((current) => ({ ...current, start: fromInputDate(event.target.value) }))} />
          <label htmlFor="climate-end">To</label>
          <input id="climate-end" aria-label="Climate history end date" className="input w-auto" type="date" value={asInputDate(range.end)} max={asInputDate(dateKey(new Date()))} min={asInputDate(range.start)} onChange={(event) => setRange((current) => ({ ...current, end: fromInputDate(event.target.value) }))} />
        </div>
      </div>

      {loading ? <p role="status" className="text-sm text-[var(--text-muted)]">Loading daily climate data…</p> : null}
      {error ? <p role="alert" className="text-sm text-[var(--text-danger)]">{error}</p> : null}
      {!loading && !error && rows.length === 0 ? <p className="text-sm text-[var(--text-muted)]">No valid daily observations are available for this date range.</p> : null}
      {stale ? <p role="status" className="text-sm text-[var(--text-warning)]">Showing cached data after an upstream error. Retrieval time and observation dates are unchanged.</p> : null}

      {!loading && !error && latest ? (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          <ClimateMetric label="External air temperature" value={latest.airTemperatureC} unit="°C" />
          <ClimateMetric label="External relative humidity" value={latest.relativeHumidityPercent} unit="%" />
          <div className="rounded-xl border border-[var(--border-primary)] bg-[var(--bg-tertiary)] p-4">
            <p className="text-xs text-[var(--text-muted)]">Latest available observation</p>
            <p className="mt-1 font-mono text-lg text-[var(--text-primary)]">{latest.date}</p>
            <p className="mt-1 text-xs text-[var(--text-muted)]">Retrieved {new Date(latest.retrievedAt).toLocaleString()}</p>
            <p className="mt-1 text-xs text-[var(--accent-primary)]">Source: NASA POWER</p>
          </div>
        </div>
      ) : null}

      {!loading && !error && rows.length > 0 ? (
        <div className="h-64 w-full" role="img" aria-label="Historical daily NASA POWER external air temperature and relative humidity chart">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={rows} margin={{ top: 8, right: 12, left: 0, bottom: 4 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--border-primary)" />
              <XAxis dataKey="date" tick={{ fill: 'var(--text-muted)', fontSize: 11 }} minTickGap={24} />
              <YAxis yAxisId="temperature" tick={{ fill: 'var(--text-muted)', fontSize: 11 }} unit="°C" width={48} />
              <YAxis yAxisId="humidity" orientation="right" tick={{ fill: 'var(--text-muted)', fontSize: 11 }} unit="%" width={44} />
              <Tooltip contentStyle={{ background: 'var(--bg-secondary)', borderColor: 'var(--border-primary)', color: 'var(--text-primary)' }} labelStyle={{ color: 'var(--text-primary)' }} />
              <Area yAxisId="temperature" type="monotone" dataKey="airTemperatureC" name="External air temperature (°C)" stroke="#fb7185" fill="#fb7185" fillOpacity={0.12} connectNulls={false} />
              <Area yAxisId="humidity" type="monotone" dataKey="relativeHumidityPercent" name="External relative humidity (%)" stroke="#38bdf8" fill="#38bdf8" fillOpacity={0.1} connectNulls={false} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      ) : null}
      <p className="text-xs text-[var(--text-muted)]">NASA POWER daily T2M (°C) and RH2M (%), AG community, {observations[0]?.latitude.toFixed(4) ?? '30.0444'}° N / {observations[0]?.longitude.toFixed(4) ?? '31.2357'}° E. Grid-cell climate context is not a greenhouse measurement.</p>
    </section>
  );
}

function ClimateMetric({ label, value, unit }: { label: string; value: number | null; unit: string }) {
  return (
    <div className="rounded-xl border border-[var(--border-primary)] bg-[var(--bg-tertiary)] p-4">
      <p className="text-xs text-[var(--text-muted)]">{label}</p>
      <p className="mt-1 font-mono text-2xl font-semibold text-[var(--text-primary)]">
        {value === null ? '—' : value.toFixed(1)}{value === null ? '' : ` ${unit}`}
      </p>
      {value === null ? <p className="mt-1 text-xs text-[var(--text-muted)]">Unavailable for this observation date</p> : null}
    </div>
  );
}
